<?php
declare(strict_types=1);
namespace App\Interface\Http\Catalog\Controller;
use App\Application\Catalog\DTO\Request\QueueSyllabusProcessingRequestDto;use App\Application\Catalog\Service\ListSyllabusDocumentExtractionsService;use App\Application\Catalog\Service\QueueSyllabusProcessingService;use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use DomainException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class SyllabusProcessingController { public function __construct(private readonly AuthService $auth,private readonly QueueSyllabusProcessingService $jobs,private readonly ListSyllabusDocumentExtractionsService $extractions,private readonly ApiResponseFactory $responses){} public function queue(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access,QueueSyllabusProcessingRequestDto $input):ResponseInterface{if(($error=$this->admin($request,$response,$access))!==null)return $error;try{return $this->responses->success($response,$this->jobs->queue($input),(string)$request->getAttribute('request_id'),202);}catch(DomainException){return $this->responses->problem($response,'VALIDATION_FAILED','Nao foi possivel enfileirar o processamento.',422,(string)$request->getAttribute('request_id'));}} public function latest(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access,string $syllabusId):ResponseInterface{if(($error=$this->admin($request,$response,$access))!==null)return $error;$job=$this->jobs->latest($syllabusId);return $job===null?$this->responses->problem($response,'RESOURCE_NOT_FOUND','Processamento nao encontrado.',404,(string)$request->getAttribute('request_id')):$this->responses->success($response,$job,(string)$request->getAttribute('request_id'));} public function listExtractions(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access,string $syllabusId):ResponseInterface{if(($error=$this->admin($request,$response,$access))!==null)return $error;return $this->responses->success($response,$this->extractions->list($syllabusId),(string)$request->getAttribute('request_id'));} private function admin(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access):?ResponseInterface{try{$user=$this->auth->currentUser($access);if(in_array('ADMIN',$user->roles,true))return null;return $this->responses->problem($response,'FORBIDDEN','Permissao insuficiente.',403,(string)$request->getAttribute('request_id'));}catch(DomainException|UnavailableUserException){return $this->responses->problem($response,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,(string)$request->getAttribute('request_id'));}} }
